def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            domains.append([-1] + versions)

        best_vector = None
        best = None
        for values in product(*domains):
            chosen = dict(zip(names, values))
            installed = {name for name, version in chosen.items() if version != -1}
            if any(name not in installed or not bounds[0] <= chosen[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue
            rows = {}
            valid = True
            for name in installed:
                version = chosen[name]
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
                rows[name] = next(row for row in packages[name] if row["version"] == version)
            if not valid:
                continue

            edges = {name: [] for name in installed}
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if (other not in installed or
                            not dep["min"] <= chosen[other] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != installed:
                continue

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in installed):
                continue
            vector = tuple(chosen[name] for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: chosen[name] for name in names if chosen[name] != -1}
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for chosen in _subsets(options, k):
            ids = {job["id"] for job in chosen}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            events = []
            for job in chosen:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(events):
                active += delta
                if active > 2:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in chosen)
            ordered_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and ordered_ids > best_ids)):
                best_value = value
                best_ids = ordered_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _subsets(items, size):
    # Enumerate index combinations without requiring an extra dependency.
    n = len(items)
    if size < 0 or size > n:
        return
    indices = list(range(size))
    if size == 0:
        yield []
        return
    while True:
        yield [items[i] for i in indices]
        for p in range(size - 1, -1, -1):
            if indices[p] != p + n - size:
                break
        else:
            return
        indices[p] += 1
        for j in range(p + 1, size):
            indices[j] = indices[j - 1] + 1


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start = data["start"]
        initial = (source, initial_mask, data["coupons"])
        best = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if best.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], coupons)]
                if coupons:
                    durations.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, remaining in durations:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, remaining)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask, remaining))
        return {"arrival": None}
    return solve


